"use strict";

function additionalVehicles({box, poly}, wheel) {
  function truck(t) {
    box(-49,-13,92,6,"#383f40");
    box(-48,-31,58,20,"#69755f");
    poly([[-48,-31],[-43,-35],[6,-35],[10,-31]],"#8a9278");
    for(const x of [-44,-29,-14,2]) {
      box(x,-31,2,20,"#4d5a4d");
      box(x+2,-31,1,17,"#92987e");
    }
    poly([[14,-13],[14,-36],[34,-36],[44,-28],[46,-14]],"#7b836c");
    poly([[19,-33],[33,-33],[40,-27],[19,-27]],"#394e55");
    box(28,-32,2,6,"#8d947e");box(20,-23,4,2,"#384546");
    box(44,-19,4,3,"#ecd195");box(-49,-13,3,2,"#ba7871");
    for(const x of [-39,-20,15,35]) wheel(x,-7,7,t*4,"#687363","#a9ab91");
  }

  function eagle(t) {
    poly([[-30,-10],[-30,-24],[-20,-26],[-10,-35],[10,-35],[23,-24],[32,-21],[32,-11]],"#877d62");
    poly([[-22,-25],[-12,-33],[9,-33],[18,-25]],"#b3a083");
    poly([[-17,-25],[-11,-31],[-2,-31],[-2,-25]],"#40555b");
    poly([[1,-31],[8,-31],[15,-25],[1,-25]],"#40555b");
    box(-12,-23,2,10,"#6b674f");box(0,-23,2,10,"#6b674f");
    box(-8,-22,4,2,"#c2ad88");box(24,-20,6,3,"#e7cf93");
    box(-31,-13,63,3,"#54574e");
    wheel(-18,-7,8,t*4,"#777666","#b0aa8c");wheel(20,-7,8,t*4,"#777666","#b0aa8c");
  }

  function articulated(t) {
    box(-5,-14,10,4,"#45494a");
    for(const x of [-44,3]) {
      poly([[x,-11],[x+37,-11],[x+33,-2],[x+28,0],[x+6,0],[x+1,-4]],"#353e40");
      for(let i=0;i<4;i++) wheel(x+6+i*8,-6,4,t*5,"#758274","#afad90");
    }
    box(-43,-29,37,17,"#737e67");box(-43,-31,36,3,"#919780");
    box(-38,-27,7,5,"#41565a");box(-28,-27,7,5,"#41565a");
    box(-18,-27,2,14,"#535e51");
    poly([[3,-12],[3,-33],[28,-33],[38,-23],[39,-12]],"#869079");
    poly([[8,-30],[17,-30],[17,-23],[8,-23]],"#40585c");
    poly([[20,-30],[27,-30],[33,-23],[20,-23]],"#40585c");
    box(35,-18,4,2,"#edcf98");
  }

  function helicopter(t) {
    // Coaxial rotor discs and the short, broad cockpit read at thumbnail size.
    poly([[-43,-2],[-47,-13],[-43,-13],[-36,-6],[-11,-3],[-9,2]],"#5d655b");
    poly([[-20,-5],[-10,-10],[10,-10],[21,-6],[32,2],[30,6],[16,9],[-9,8],[-22,2]],"#6d7969");
    poly([[5,-8],[13,-8],[23,-3],[28,1],[13,1]],"#354e58");
    box(13,-6,2,6,"#9da891");box(-14,-5,10,3,"#929a82");
    poly([[-4,1],[9,1],[-7,9],[-17,9]],"#485c55");
    box(11,4,11,3,"#4b564e");box(21,4,14,2,"#626d60");
    box(-6,-19,2,10,"#434b50");
    const span=23+Math.round(16*Math.abs(Math.sin(t*13)));
    box(-6-span,-18,span*2,2,"#535762");
    box(-6-span+4,-14,span*2-8,1,"#a1a19a");
    for(const x of [-10,19]){box(x,7,1,4,"#505552");box(x-1,11,4,2,"#353c40")}
  }

  function bomber(t) {
    poly([[-9,-3],[-29,-20],[-23,-21],[10,-4]],"#85919a");
    poly([[-46,-3],[-49,-18],[-44,-18],[-32,-4]],"#727d88");
    poly([[-49,-3],[15,-5],[37,-4],[49,0],[40,3],[8,5],[-36,3]],"#b5b9b3");
    poly([[-43,1],[45,0],[38,3],[4,5],[-33,3]],"#75808a");
    poly([[11,0],[-18,22],[-29,22],[-11,2]],"#949fa8");
    poly([[-35,1],[-48,9],[-54,9],[-45,1]],"#75818e");
    for(const [x,y] of [[-16,-13],[-8,-8],[-12,12],[-23,18]]) {
      box(x-4,y-1,14,3,"#68747b");
      const tip=2+Math.round(2*Math.abs(Math.sin(t*13+x)));
      box(x+8,y-tip,1,tip*2+1,"#545e67");
    }
    box(31,-4,7,2,"#425764");
  }

  return [
    {name:"Ka-52",draw:helicopter,duration:7,margin:52,altitude:.19,muzzle:[35,5]},
    {name:"Tu-95",draw:bomber,duration:6,margin:58,altitude:.16},
    {name:"RMMV HX 8×8",draw:truck,duration:8,margin:55,exhaust:[-50,-13]},
    {name:"Bv410",draw:articulated,duration:8,margin:49,exhaust:[-45,-15]},
    {name:"Eagle V",draw:eagle,duration:6,margin:36,exhaust:[-32,-12]}
  ];
}
